"""The field system: one container that FUSES its children.

**There is one input component, not seven.** Measured across the design's six
shapes, the container is identical every time — 1px border, the sunken fill,
a 12px radius and the same width. What differs is only what was fused into
it, and the gap that follows from that. So "phone", "money", "link" and
"card" are not types: they are the same container with different children,
and they ship as libraries rather than as components.

**Fused, not merely arranged.** The children share the container's edge and
read as one control, with no seam between them — which is what separates a
phone field from a picker sitting next to an input. A plain row could not do
that.

The parts are all widgets and all children, in the order they sit::

    Input(
        Dropdown(self.countries, value=self.iso),
        Demarcation(),
        TextInput(value=self.phone, on_change=self.set_phone),
        label="Phone number",
    )

so there is no leading/trailing slot to choose between, and no limit of one
per side. The order IS the layout.

**Two axes, orthogonal to every composition.** ``size`` scales the box and
everything fused into it; ``status`` carries error and success through one
mechanism — the same trailing position, the same border, the same message
row, differing by a colour and a glyph.
"""
from typing import Any, Callable, Literal

from .base import BaseWidget, WidgetChild
from .layout import MultiChildLayout

#: The libraries, and the children each one fuses. Data, not control flow:
#: the runtime reads this table, so a new library is a row here and a row
#: there — never a new branch in the parser, the generator or the renderer.
#:
#: Each entry names the parts in visual order. ``input`` is the control.
FIELD_RECIPES: dict[str, dict[str, Any]] = {
    "phone": {
        "parts": ("dropdown", "demarcation", "input"),
        "gap": 0,
    },
    "money": {
        "parts": ("adornment", "input", "dropdown"),
        "gap": 4,
    },
    "link": {
        # The SAME shape as phone, with an adornment where phone has a
        # picker. That parallel is the point: a protocol you cannot change
        # and a country you can are the same composition, differing only in
        # whether the left-hand part is inert.
        "parts": ("adornment", "demarcation", "input"),
        "gap": 0,
    },
    "card": {
        "parts": ("image", "input"),
        "gap": 10,
    },
    # The date recipes fuse one part, the segments a DateSegments draws, in
    # place of a text control: the box is the field's, the parts its own.
    "date": {"parts": ("segments",), "gap": 0},
    "time": {"parts": ("segments",), "gap": 0},
    "datetime": {"parts": ("segments",), "gap": 0},
}


class Adornment(BaseWidget):
    """Inert text fused into a field — the ``$`` on a money input.

    Not editable and not clickable: it is a label for the value beside it,
    so it takes no pointer and no tab stop. It sits at the placeholder
    colour until the field has something in it, then promotes to the text
    colour, which is what makes an empty money field read as a prompt
    rather than as a value of zero.
    """

    widget_type = "Adornment"

    def __init__(self, text: str = "", **kwargs: Any):
        super().__init__(**kwargs)
        self.text = text

    def props(self) -> dict[str, Any]:
        return {"text": self.text}


class Demarcation(BaseWidget):
    """The hairline between two fused parts — a widget, not a flag.

    A 1px rule the height of the text, with room either side. It separates
    a fused part from the control WITHOUT closing the box, which is the
    difference between a phone field and two inputs side by side.

    It is a child like any other because it is optional and positional: a
    phone field reads perfectly well without one, and where it goes is a
    composition decision rather than a property of the container.
    """

    widget_type = "Demarcation"


class Dropdown(BaseWidget):
    """A picker fused into a field — one primitive, either side.

    The country picker on a phone field and the currency picker on a money
    field are the same widget: same button, same 12px chevron, same panel.
    They differ in their options and in which side they sit, and neither of
    those is a reason for two components.

    ``options`` is a list of ``{"value": …, "label": …}`` dicts, or plain
    strings when the value and the label are the same thing. An option may
    also carry a leading marker — ``image`` (a URL: a flag), ``icon``,
    ``dot`` or ``avatar``, in that order of precedence — a ``code`` drawn
    small right after the label (an ISO code, a currency code: "SN"), a
    trailing ``meta`` ("+221"), a ``desc`` line, and ``keywords``: extra
    text the search row matches without showing it. ``search=True`` adds
    the filter row the country picker has, which is worth it past a couple
    of dozen options and noise below that; it matches the label, the
    description, the code, the meta and the keywords — never the value,
    which is usually an id nobody sees. An identifier worth finding a row
    by belongs in ``code`` or ``meta`` when it is shown, and in
    ``keywords`` when it is not.

    The button shows the chosen option as its row does — marker, label,
    code, meta — and only the label gives way when space is short: it
    ellipsises, so a long name never pushes the code, the meta or a control
    beside the picker out of the field. ``trigger="compact"`` drops the
    label from the button — a flag, "SN" and "+221" — while the list keeps
    every row's full name. In both, the button's accessible name is the
    whole label, the code and the meta ("Senegal, SN, +221").
    """

    widget_type = "Dropdown"

    def __init__(
        self,
        options: list | None = None,
        *,
        value: Any = None,
        on_change: Callable | None = None,
        search: bool = False,
        panel_width: int | None = None,
        placeholder: str = "",
        trigger: Literal["full", "compact"] = "full",
        **kwargs: Any,
    ):
        super().__init__(**kwargs)
        self.options = options or []
        self.value = value
        self.on_change = on_change
        self.search = search
        self.panel_width = panel_width
        self.placeholder = placeholder
        self.trigger = trigger

    def props(self) -> dict[str, Any]:
        p: dict[str, Any] = {"options": self.options, "value": self.value}
        if self.search:
            p["search"] = True
        if self.panel_width is not None:
            p["panel_width"] = self.panel_width
        if self.placeholder:
            p["placeholder"] = self.placeholder
        if self.trigger != "full":
            p["trigger"] = self.trigger
        return p


class Input(MultiChildLayout):
    """The field container. It FUSES its children into one control.

    Everything visible in a field is a child, in the order it sits::

        Input(Icon("mail"), TextInput(value=self.email,
                                      on_change=self.set_email),
              label="Email", hint="We only mail about deliveries")

    The container owns the **label above** and the **hint or message below**
    — they are rows of the wrapper rather than fused parts, so every
    composition gets them for free and no app has to build a second label
    system.

    **Defaults are the container's, and every one can be changed.** The
    border, the fill, the radius and the width are one set of values rather
    than constants baked per shape, so a field can be given a different edge
    without becoming a new variant. ``gap`` follows from what is fused
    unless it is given.

    ``size`` is ``"md"`` (40px) or ``"lg"`` (44px), and everything fused in
    scales with it. ``status`` is ``"error"`` or ``"success"`` — one
    mechanism, differing by a colour and a glyph, so a field that can go red
    can go green without a second code path.

    ``value`` is the composite's value for a surrounding ``Field``. A field
    fusing a country picker to a number has a true value no single control
    holds, and without it ``Field`` reads the first native control inside —
    the bare digits. With it, ``required``, the validators and the submitted
    values all read ``value`` instead. It is text, like every field value.
    """

    widget_type = "Input"

    def __init__(
        self,
        *children: WidgetChild,
        label: str | None = None,
        hint: str | None = None,
        message: str | None = None,
        status: Literal["error", "success"] | None = None,
        size: Literal["md", "lg"] = "md",
        gap: int | None = None,
        disabled: bool = False,
        value: str | None = None,
        key: str | None = None,
        **kwargs: Any,
    ):
        super().__init__(*children, key=key, disabled=disabled, **kwargs)
        self.label = label
        self.hint = hint
        self.message = message
        self.status = status
        self.size = size
        self.gap = gap
        self.value = value

    def props(self) -> dict[str, Any]:
        p: dict[str, Any] = {}
        for name in ("label", "hint", "message", "status", "value"):
            value = getattr(self, name)
            if value is not None:
                p[name] = value
        if self.size != "md":
            p["size"] = self.size
        if self.gap is not None:
            p["gap"] = self.gap
        return p


class _Library(BaseWidget):
    """Base for the shipped compositions.

    A library is an :class:`Input` whose children are known — so it is the
    SAME node with a recipe name on it, and the runtime fuses the parts from
    :data:`FIELD_RECIPES`. That is what keeps a new library a row of data
    rather than a branch in the parser, the generator and the renderer.

    Everything the container takes, a library takes too: they are forwarded
    unchanged rather than re-declared, so the two can never drift.
    """

    #: Set by each subclass; the key into :data:`FIELD_RECIPES`.
    recipe = ""

    def __init__(
        self,
        *,
        value: str | Any = "",
        on_change: Callable | None = None,
        on_submit: Callable | None = None,
        placeholder: str = "",
        label: str | None = None,
        hint: str | None = None,
        message: str | None = None,
        status: Literal["error", "success"] | None = None,
        size: Literal["md", "lg"] = "md",
        disabled: bool = False,
        key: str | None = None,
        **kwargs: Any,
    ):
        super().__init__(key=key, disabled=disabled, **kwargs)
        self.value = value
        self.on_change = on_change
        self.on_submit = on_submit
        self.placeholder = placeholder
        self.label = label
        self.hint = hint
        self.message = message
        self.status = status
        self.size = size

    def props(self) -> dict[str, Any]:
        p: dict[str, Any] = {"recipe": self.recipe, "value": self.value}
        for name in ("placeholder", "label", "hint", "message", "status"):
            value = getattr(self, name)
            if value:
                p[name] = value
        if self.size != "md":
            p["size"] = self.size
        return p


class PhoneInput(_Library):
    """A number field with a country picker fused to its left.

        PhoneInput(value=self.phone, on_change=self.set_phone,
                   country="NG", label="Phone number")

    The picker is an ordinary :class:`Dropdown` and the hairline an ordinary
    :class:`Demarcation` — this is the composition, named. Write it out with
    :class:`Input` when you want a different set of countries, a different
    separator, or none.
    """

    widget_type = "PhoneInput"
    recipe = "phone"

    def __init__(self, *, country: str = "US", countries: list | None = None,
                 on_country_change: Callable | None = None, **kwargs: Any):
        super().__init__(**kwargs)
        self.country = country
        self.countries = countries
        self.on_country_change = on_country_change

    def props(self) -> dict[str, Any]:
        p = super().props()
        p["country"] = self.country
        if self.countries:
            p["countries"] = self.countries
        return p


class MoneyInput(_Library):
    """An amount field: a currency symbol fused left, a picker fused right.

        MoneyInput(value=self.amount, on_change=self.set_amount,
                   currency="NGN", label="Sale amount")

    The picker on the right is the same :class:`Dropdown` the phone field
    puts on the left.
    """

    widget_type = "MoneyInput"
    recipe = "money"

    def __init__(self, *, currency: str = "USD", currencies: list | None = None,
                 symbol: str | None = None,
                 on_currency_change: Callable | None = None, **kwargs: Any):
        super().__init__(**kwargs)
        self.currency = currency
        self.currencies = currencies
        self.symbol = symbol
        self.on_currency_change = on_currency_change

    def props(self) -> dict[str, Any]:
        p = super().props()
        p["currency"] = self.currency
        if self.currencies:
            p["currencies"] = self.currencies
        if self.symbol:
            p["symbol"] = self.symbol
        return p


class LinkInput(_Library):
    """A URL field with the protocol fused left, behind a hairline.

        LinkInput(value=self.site, on_change=self.set_site,
                  protocol="https://", label="Website")

    The same composition as :class:`PhoneInput` — something fused left, a
    :class:`Demarcation`, then the control — with an :class:`Adornment` in
    place of the picker. A protocol you cannot change and a country you can
    are the same shape; only the left-hand part differs in whether it is
    inert.
    """

    widget_type = "LinkInput"
    recipe = "link"

    def __init__(self, *, protocol: str = "https://", **kwargs: Any):
        super().__init__(**kwargs)
        self.protocol = protocol

    def props(self) -> dict[str, Any]:
        p = super().props()
        p["protocol"] = self.protocol
        return p


class CardInput(_Library):
    """A card-number field with the network mark fused left.

        CardInput(value=self.card, on_change=self.set_card,
                  label="Card number")

    ``brand`` picks the mark — ``"mastercard"``, ``"visa"``, ``"amex"`` or
    ``"generic"``. It is an image rather than an icon because a card network
    is a logo with its own colours, not a glyph that takes the surrounding
    text colour.
    """

    widget_type = "CardInput"
    recipe = "card"

    def __init__(self, *, brand: str = "mastercard", **kwargs: Any):
        super().__init__(**kwargs)
        self.brand = brand

    def props(self) -> dict[str, Any]:
        p = super().props()
        p["brand"] = self.brand
        return p


class _DateLibrary(_Library):
    """Base for the date recipes: an :class:`Input` with DateSegments fused
    in, so its value is an ISO string or ``None`` and it has no
    placeholder — its parts show their own (mm/dd/yyyy, from the locale).

    Every keyword the field surface takes (label, hint, message, status,
    size, disabled) it takes too, plus ``value``, ``on_change`` and
    ``on_submit``; each subclass adds the calendar keywords its kind reads,
    in its signature, which the compiler's ``_FIELD_LIBRARIES`` row and a
    test pin.
    """

    def __init__(
        self,
        *,
        value: str | Any = None,
        on_change: Callable | None = None,
        on_submit: Callable | None = None,
        label: str | None = None,
        hint: str | None = None,
        message: str | None = None,
        status: Literal["error", "success"] | None = None,
        size: Literal["md", "lg"] = "md",
        disabled: bool | Any = False,
        key: str | None = None,
        **kwargs: Any,
    ):
        BaseWidget.__init__(self, key=key, disabled=disabled, **kwargs)
        self.value = value
        self.on_change = on_change
        self.on_submit = on_submit
        self.placeholder = ""
        self.label = label
        self.hint = hint
        self.message = message
        self.status = status
        self.size = size

    #: The recipe's own calendar keywords, set by each subclass.
    _EXTRA: tuple = ()

    def props(self) -> dict[str, Any]:
        p = super().props()
        if self.value is None:
            del p["value"]
        for name in self._EXTRA:
            value = getattr(self, name)
            if value is not None:
                p[name] = value
        return p


class DateInput(_DateLibrary):
    """A date typed into a field — month, day and year fused into the
    field's box, in the order the locale writes them.

        DateInput(value=self.due, on_change=self.set_due, label="Due",
                  first_date="2025-01-01")

    ``value`` is ``"2025-12-16"`` or ``None``, and ``on_change`` hears a
    date once every part is filled and it is a real day inside the bounds
    (``first_date``, ``last_date``, ``disabled_weekdays``,
    ``disabled_dates``, ``selectable_day_predicate``). Left half typed it
    says ``error_format_text``, and a whole date it refuses
    ``error_invalid_text``, in its message row, unless ``message=`` says
    something else. Written out, it is ``Input(DateSegments(…))``.
    """

    widget_type = "DateInput"
    recipe = "date"
    _EXTRA = ("first_date", "last_date", "current_date",
              "selectable_day_predicate", "disabled_dates",
              "disabled_weekdays", "starting_day_of_week", "locale",
              "time_zone", "error_format_text", "error_invalid_text")

    def __init__(self, *, first_date: str | None = None,
                 last_date: str | None = None,
                 current_date: str | None = None,
                 selectable_day_predicate: Callable | None = None,
                 disabled_dates: list | None = None,
                 disabled_weekdays: list | None = None,
                 starting_day_of_week: int | None = None,
                 locale: str | None = None, time_zone: str | None = None,
                 error_format_text: str | None = None,
                 error_invalid_text: str | None = None, **kwargs: Any):
        super().__init__(**kwargs)
        self.first_date = first_date
        self.last_date = last_date
        self.current_date = current_date
        self.selectable_day_predicate = selectable_day_predicate
        self.disabled_dates = disabled_dates
        self.disabled_weekdays = disabled_weekdays
        self.starting_day_of_week = starting_day_of_week
        self.locale = locale
        self.time_zone = time_zone
        self.error_format_text = error_format_text
        self.error_invalid_text = error_invalid_text


class TimeInput(_DateLibrary):
    """A time of day typed into a field — hour, minute, AM/PM on a 12-hour
    clock, and seconds with ``seconds=True``.

        TimeInput(value=self.at, on_change=self.set_at, label="Starts at",
                  minute_interval=15, show_zone=True)

    ``value`` is ``"14:30"`` (``"14:30:15"`` with seconds), always 24
    hours whatever the field shows, or ``None``. ``first_time`` and
    ``last_time`` bound it; ``show_zone`` adds the zone's short name.
    """

    widget_type = "TimeInput"
    recipe = "time"
    _EXTRA = ("seconds", "use_24h_format", "minute_interval", "first_time",
              "last_time", "show_zone", "time_zone", "locale", "picker",
              "error_format_text", "error_invalid_text")

    def __init__(self, *, seconds: bool | None = None,
                 use_24h_format: bool | None = None,
                 minute_interval: int | None = None,
                 first_time: str | None = None, last_time: str | None = None,
                 show_zone: bool | None = None, time_zone: str | None = None,
                 locale: str | None = None, picker: bool | None = None,
                 error_format_text: str | None = None,
                 error_invalid_text: str | None = None, **kwargs: Any):
        super().__init__(**kwargs)
        self.seconds = seconds
        self.use_24h_format = use_24h_format
        self.minute_interval = minute_interval
        self.first_time = first_time
        self.last_time = last_time
        self.show_zone = show_zone
        self.time_zone = time_zone
        self.locale = locale
        self.picker = picker
        self.error_format_text = error_format_text
        self.error_invalid_text = error_invalid_text


class DateTimeInput(_DateLibrary):
    """A date and a time of day typed into one field — the design's Date &
    Time field: ``mm/dd/yyyy, hh:mm:ss AM EST``.

        DateTimeInput(value=self.when, on_change=self.set_when,
                      seconds=True, show_zone=True, label="Date")

    ``value`` is ``"2025-12-16T14:30"`` — wall-clock time with no offset,
    as ``datetime-local`` holds it — or ``None``. It takes DateInput's
    keywords and TimeInput's.
    """

    widget_type = "DateTimeInput"
    recipe = "datetime"
    _EXTRA = DateInput._EXTRA + ("seconds", "use_24h_format",
                                 "minute_interval", "first_time",
                                 "last_time", "show_zone", "picker")

    def __init__(self, *, first_date: str | None = None,
                 last_date: str | None = None,
                 current_date: str | None = None,
                 selectable_day_predicate: Callable | None = None,
                 disabled_dates: list | None = None,
                 disabled_weekdays: list | None = None,
                 starting_day_of_week: int | None = None,
                 locale: str | None = None, time_zone: str | None = None,
                 error_format_text: str | None = None,
                 error_invalid_text: str | None = None,
                 seconds: bool | None = None,
                 use_24h_format: bool | None = None,
                 minute_interval: int | None = None,
                 first_time: str | None = None, last_time: str | None = None,
                 show_zone: bool | None = None, picker: bool | None = None,
                 **kwargs: Any):
        super().__init__(**kwargs)
        # DateInput's keywords and TimeInput's, each kept under its own
        # name from the parameter of that name.
        for name in self._EXTRA:
            setattr(self, name, locals()[name])


#: Every widget this module ships, by name. The parser and the exports read
#: it, so a widget cannot exist here and be missing from either.
FIELD_WIDGETS = {
    "Input": Input,
    "Adornment": Adornment,
    "Demarcation": Demarcation,
    "Dropdown": Dropdown,
    "PhoneInput": PhoneInput,
    "MoneyInput": MoneyInput,
    "LinkInput": LinkInput,
    "CardInput": CardInput,
    "DateInput": DateInput,
    "TimeInput": TimeInput,
    "DateTimeInput": DateTimeInput,
}

#: The libraries alone — the ones that carry a `recipe` and expand from
#: :data:`FIELD_RECIPES` rather than from explicit children.
LIBRARY_WIDGETS = {
    name: cls for name, cls in FIELD_WIDGETS.items()
    if getattr(cls, "recipe", "")
}
